CREATE TYPE public.app_role AS ENUM ('owner','buyer','admin');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'buyer');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE FUNCTION public.is_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='owner') $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_admin());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE FUNCTION public.create_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,CASE WHEN new.raw_user_meta_data->>'account_type'='owner' THEN 'owner'::public.app_role ELSE 'buyer'::public.app_role END); RETURN new; END $$;
CREATE TRIGGER account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account();
CREATE TABLE public.property_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
GRANT SELECT ON public.property_categories TO anon,authenticated; GRANT ALL ON public.property_categories TO service_role; GRANT INSERT,UPDATE,DELETE ON public.property_categories TO authenticated;
ALTER TABLE public.property_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_read ON public.property_categories FOR SELECT USING(true); CREATE POLICY categories_admin ON public.property_categories FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), publisher_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL, purpose text NOT NULL CHECK(purpose IN ('sale','rent')), price numeric NOT NULL CHECK(price>=0), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','ILS','JOD')), city text NOT NULL, neighborhood text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', latitude numeric, longitude numeric, bedrooms integer NOT NULL DEFAULT 0 CHECK(bedrooms>=0), bathrooms integer NOT NULL DEFAULT 0 CHECK(bathrooms>=0), area numeric NOT NULL CHECK(area>0), floor integer NOT NULL DEFAULT 0, amenities text[] NOT NULL DEFAULT '{}', source text NOT NULL DEFAULT 'owner' CHECK(source IN ('owner','agency')), approval text NOT NULL DEFAULT 'pending' CHECK(approval IN ('pending','approved','rejected')), status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','sold','rented')), featured boolean NOT NULL DEFAULT false, rejection_reason text, views integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.properties TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties TO authenticated; GRANT ALL ON public.properties TO service_role;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
CREATE POLICY properties_public ON public.properties FOR SELECT TO anon,authenticated USING(approval='approved' AND status='available');
CREATE POLICY properties_own_read ON public.properties FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.is_admin());
CREATE POLICY properties_insert ON public.properties FOR INSERT TO authenticated WITH CHECK(public.is_admin() OR (public.is_owner() AND owner_id=auth.uid() AND publisher_id=auth.uid() AND approval='pending' AND source='owner'));
CREATE POLICY properties_update ON public.properties FOR UPDATE TO authenticated USING(public.is_admin() OR (public.is_owner() AND owner_id=auth.uid())) WITH CHECK(public.is_admin() OR owner_id=auth.uid());
CREATE POLICY properties_delete ON public.properties FOR DELETE TO authenticated USING(public.is_admin() OR owner_id=auth.uid());
CREATE FUNCTION public.guard_property() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN IF TG_OP='UPDATE' THEN IF new.owner_id<>old.owner_id OR new.publisher_id<>old.publisher_id OR new.status<>old.status OR new.source<>old.source OR new.featured<>old.featured THEN RAISE EXCEPTION 'Only agency administrators may change controlled fields'; END IF; new.approval:='pending'; new.rejection_reason:=NULL; ELSE new.approval:='pending'; END IF; END IF; new.updated_at:=now(); RETURN new; END $$;
CREATE TRIGGER property_guard BEFORE INSERT OR UPDATE ON public.properties FOR EACH ROW EXECUTE FUNCTION public.guard_property();
CREATE TABLE public.property_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE, storage_path text NOT NULL, position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.property_images TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.property_images TO authenticated; GRANT ALL ON public.property_images TO service_role;
ALTER TABLE public.property_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY images_read ON public.property_images FOR SELECT USING(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id));
CREATE POLICY images_write ON public.property_images FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND (p.owner_id=auth.uid() OR public.is_admin()))) WITH CHECK(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND (p.owner_id=auth.uid() OR public.is_admin())));
CREATE TABLE public.favorites(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, property_id uuid NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,property_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY; CREATE POLICY favorites_own ON public.favorites FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.inquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid REFERENCES public.properties(id) ON DELETE SET NULL, user_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL, phone text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','viewing','negotiating','successful','lost')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.inquiries TO authenticated; GRANT ALL ON public.inquiries TO service_role;
ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY inquiry_read ON public.inquiries FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin() OR EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND p.owner_id=auth.uid()));
CREATE POLICY inquiry_insert ON public.inquiries FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='new'); CREATE POLICY inquiry_admin ON public.inquiries FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.lead_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inquiry_id uuid NOT NULL REFERENCES public.inquiries(id) ON DELETE CASCADE, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.lead_notes TO authenticated; GRANT ALL ON public.lead_notes TO service_role; ALTER TABLE public.lead_notes ENABLE ROW LEVEL SECURITY; CREATE POLICY notes_admin ON public.lead_notes FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.viewing_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id), scheduled_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','confirmed','cancelled','completed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.viewing_appointments TO authenticated; GRANT ALL ON public.viewing_appointments TO service_role; ALTER TABLE public.viewing_appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointments_read ON public.viewing_appointments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin()); CREATE POLICY appointments_insert ON public.viewing_appointments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='requested'); CREATE POLICY appointments_admin ON public.viewing_appointments FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.commission_agreements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL UNIQUE REFERENCES public.properties(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('percentage','fixed')), rate numeric NOT NULL CHECK(rate>=0), terms text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','due','paid','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(kind<>'percentage' OR rate<=100));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.commission_agreements TO authenticated; GRANT ALL ON public.commission_agreements TO service_role; ALTER TABLE public.commission_agreements ENABLE ROW LEVEL SECURITY; CREATE POLICY commissions_admin ON public.commission_agreements FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL UNIQUE REFERENCES public.properties(id), agreement_id uuid NOT NULL REFERENCES public.commission_agreements(id), amount numeric NOT NULL CHECK(amount>0), commission numeric NOT NULL CHECK(commission>=0), confirmed_by uuid NOT NULL REFERENCES public.profiles(id), completed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.transactions TO authenticated; GRANT ALL ON public.transactions TO service_role; ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY transactions_admin ON public.transactions FOR SELECT TO authenticated USING(public.is_admin());
CREATE TABLE public.commission_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agreement_id uuid NOT NULL REFERENCES public.commission_agreements(id), amount numeric NOT NULL CHECK(amount>0), paid_at date NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.commission_payments TO authenticated; GRANT ALL ON public.commission_payments TO service_role; ALTER TABLE public.commission_payments ENABLE ROW LEVEL SECURITY; CREATE POLICY payments_admin ON public.commission_payments FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE FUNCTION public.confirm_transaction(p_property uuid,p_amount numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.commission_agreements; t uuid; p public.properties; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator confirmation required'; END IF; IF p_amount<=0 THEN RAISE EXCEPTION 'Invalid transaction amount'; END IF; SELECT * INTO p FROM public.properties WHERE id=p_property FOR UPDATE; IF p.approval<>'approved' OR p.status NOT IN ('available','reserved') THEN RAISE EXCEPTION 'Property must be approved and active'; END IF; SELECT * INTO a FROM public.commission_agreements WHERE property_id=p_property FOR UPDATE; IF a.id IS NULL OR a.status='cancelled' THEN RAISE EXCEPTION 'Active commission agreement required'; END IF; INSERT INTO public.transactions(property_id,agreement_id,amount,commission,confirmed_by) VALUES(p_property,a.id,p_amount,CASE WHEN a.kind='percentage' THEN round(p_amount*a.rate/100,2) ELSE a.rate END,auth.uid()) RETURNING id INTO t; UPDATE public.properties SET status=CASE WHEN purpose='sale' THEN 'sold' ELSE 'rented' END WHERE id=p_property; UPDATE public.commission_agreements SET status='due' WHERE id=a.id; RETURN t; END $$;
REVOKE ALL ON FUNCTION public.confirm_transaction(uuid,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.confirm_transaction(uuid,numeric) TO authenticated;
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), message text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_own ON public.notifications FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.property_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.notifications(user_id,message) SELECT user_id,'عقار جديد بانتظار المراجعة: '||new.title FROM public.user_roles WHERE role='admin'; ELSIF new.approval IS DISTINCT FROM old.approval THEN INSERT INTO public.notifications(user_id,message) VALUES(new.owner_id,'تم تحديث حالة إعلانك: '||new.title||' — '||new.approval); END IF; RETURN new; END $$;
CREATE TRIGGER property_notifications AFTER INSERT OR UPDATE ON public.properties FOR EACH ROW EXECUTE FUNCTION public.property_notification();
CREATE TABLE public.website_settings(key text PRIMARY KEY, value text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.website_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.website_settings TO authenticated; GRANT ALL ON public.website_settings TO service_role; ALTER TABLE public.website_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY settings_read ON public.website_settings FOR SELECT USING(true); CREATE POLICY settings_admin ON public.website_settings FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY storage_own_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='property-images' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY storage_read ON storage.objects FOR SELECT USING(bucket_id='property-images' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_admin() OR EXISTS(SELECT 1 FROM public.property_images i JOIN public.properties p ON p.id=i.property_id WHERE i.storage_path=name AND p.approval='approved' AND p.status='available')));
CREATE POLICY storage_own_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='property-images' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_admin()));
CREATE INDEX properties_owner_idx ON public.properties(owner_id); CREATE INDEX properties_public_idx ON public.properties(approval,status,city,purpose); CREATE INDEX inquiries_property_idx ON public.inquiries(property_id); CREATE INDEX inquiries_user_idx ON public.inquiries(user_id); CREATE INDEX images_property_idx ON public.property_images(property_id);